public class SloBurn {
    static final double SLO = 0.999;
    static final double BUDGET = 1 - SLO;          // 0.1 percent of requests may fail
    static final int RPS = 2000;                   // assumed constant request rate
    static final int WINDOW_DAYS = 30;

    // error ratio per minute for a 24-hour day (assumed incident from minute 600 to 630)
    static double errorRatio(int minute) {
        if (minute >= 600 && minute < 630) return 0.05;   // 5 percent errors
        return 0.0003;                                       // background 0.03 percent
    }

    static double burn(double[] r, int endMinute, int windowMin) {
        double sum = 0;
        int from = Math.max(0, endMinute - windowMin + 1);
        for (int m = from; m <= endMinute; m++) sum += r[m];
        return (sum / (endMinute - from + 1)) / BUDGET;
    }

    public static void main(String[] args) {
        long perMonth = (long) RPS * 86400L * WINDOW_DAYS;
        System.out.printf("requests per 30 days   : %,d%n", perMonth);
        System.out.printf("error budget (requests): %,.0f%n", perMonth * BUDGET);
        System.out.printf("error budget (minutes) : %.1f%n", WINDOW_DAYS * 24 * 60 * BUDGET);
        double[] r = new double[1440];
        for (int m = 0; m < 1440; m++) r[m] = errorRatio(m);
        boolean fast = false, slow = false;
        double consumed = 0;
        for (int m = 0; m < 1440; m++) {
            consumed += r[m] * RPS * 60;
            double b1h = burn(r, m, 60), b5m = burn(r, m, 5);
            double b6h = burn(r, m, 360), b30m = burn(r, m, 30);
            if (!fast && b1h >= 14.4 && b5m >= 14.4) {
                fast = true;
                System.out.printf("PAGE 14.4x at minute %d: burn(1h)=%.1f burn(5m)=%.1f%n",
                    m, b1h, b5m);
            }
            if (!slow && b6h >= 6 && b30m >= 6) {
                slow = true;
                System.out.printf("PAGE 6x    at minute %d: burn(6h)=%.1f burn(30m)=%.1f%n",
                    m, b6h, b30m);
            }
        }
        System.out.printf("budget consumed that day: %.1f percent of the 30-day budget%n",
            100 * consumed / (perMonth * BUDGET));
        double h = 0.05 / BUDGET;
        System.out.printf("burn rate during incident: %.0f -> budget gone in %.1f hours%n",
            h, WINDOW_DAYS * 24 / h);
    }
}

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

public class Flags {
    static int bucket(String flag, String user) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] h = md.digest((flag + ":" + user).getBytes(StandardCharsets.UTF_8));
        int v = ((h[0] & 0xff) << 24) | ((h[1] & 0xff) << 16)
              | ((h[2] & 0xff) << 8) | (h[3] & 0xff);
        return (int) ((v & 0xffffffffL) % 100);
    }
    public static void main(String[] a) throws Exception {
        int users = 100_000;
        for (int pct : new int[] {1, 5, 25, 50}) {
            int on = 0;
            for (int u = 0; u < users; u++) if (bucket("new-checkout", "user-" + u) < pct) on++;
            System.out.printf("rollout %2d%% -> %6d of %d users enabled (%.2f%%)%n",
                pct, on, users, 100.0 * on / users);
        }
        int stay = 0, was = 0;
        for (int u = 0; u < users; u++) {
            boolean at5 = bucket("new-checkout", "user-" + u) < 5;
            boolean at25 = bucket("new-checkout", "user-" + u) < 25;
            if (at5) { was++; if (at25) stay++; }
        }
        System.out.printf("users enabled at 5%%: %d, still enabled at 25%%: %d%n", was, stay);
        System.out.println("user-42 buckets: new-checkout=" + bucket("new-checkout", "user-42")
            + " dark-mode=" + bucket("dark-mode", "user-42"));
    }
}

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Base64;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class Jwt {
    static final Base64.Encoder ENC = Base64.getUrlEncoder().withoutPadding();
    static final byte[] KEY =
        "demo-secret-key-do-not-use-in-production!".getBytes(StandardCharsets.UTF_8);

    static String b64(String s) { return ENC.encodeToString(s.getBytes(StandardCharsets.UTF_8)); }
    static String sign(String data) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(KEY, "HmacSHA256"));
        return ENC.encodeToString(mac.doFinal(data.getBytes(StandardCharsets.UTF_8)));
    }
    static String issue(String sub, String scope, long exp) throws Exception {
        String head = b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}");
        String body = b64("{\"sub\":\"" + sub + "\",\"scope\":\"" + scope
            + "\",\"exp\":" + exp + "}");
        return head + "." + body + "." + sign(head + "." + body);
    }
    static String verify(String token, long now) throws Exception {
        String[] p = token.split("\\.");
        if (p.length != 3) return "REJECT malformed";
        String head = new String(Base64.getUrlDecoder().decode(p[0]), StandardCharsets.UTF_8);
        if (!head.contains("\"alg\":\"HS256\"")) return "REJECT algorithm not allowed";
        boolean ok = MessageDigest.isEqual(sign(p[0] + "." + p[1]).getBytes(StandardCharsets.UTF_8),
                                           p[2].getBytes(StandardCharsets.UTF_8));
        if (!ok) return "REJECT bad signature";
        String body = new String(Base64.getUrlDecoder().decode(p[1]), StandardCharsets.UTF_8);
        long exp = Long.parseLong(body.replaceAll(".*\"exp\":(\\d+).*", "$1"));
        if (now >= exp) return "REJECT expired";
        return "ACCEPT " + body;
    }
    public static void main(String[] args) throws Exception {
        long now = 1_700_000_000L;
        String t = issue("user-42", "orders:read", now + 900);
        System.out.println("token parts: " + t.split("\\.").length + ", length " + t.length());
        System.out.println("valid          : " + verify(t, now));
        System.out.println("after expiry   : " + verify(t, now + 901));
        String[] p = t.split("\\.");
        String forged = p[0] + "." + b64("{\"sub\":\"user-42\",\"scope\":\"admin\",\"exp\":"
            + (now + 900) + "}") + "." + p[2];
        System.out.println("tampered scope : " + verify(forged, now));
        String none = b64("{\"alg\":\"none\",\"typ\":\"JWT\"}") + "." + p[1] + ".";
        System.out.println("alg none       : " + verify(none + "x", now));
    }
}

