random.seed(7)
N=1000; SLOT=0.1; ACCEPT=100          # 1000 clients, server accepts 100 requests per 100 ms slot
def run(name, delay):
    nxt=[0.0]*N; done=[False]*N; attempts=0; peak=0; load={}; finish=0
    for rnd in range(40):
        pending=[i for i in range(N) if not done[i]]
        if not pending: break
        slots={}
        for i in pending: slots.setdefault(int(nxt[i]/SLOT),[]).append(i)
        for s,ids in sorted(slots.items()):
            peak=max(peak,len(ids)) if rnd>0 else peak; attempts+=len(ids)
            for k,i in enumerate(ids):
                if k<ACCEPT: done[i]=True; finish=max(finish,(s+1)*SLOT)
                else: nxt[i]=s*SLOT+delay(i,rnd)
    print("%-26s attempts=%5d  peak retry/slot=%4d  done after %.1f s"%(name,attempts,peak,finish))
base=0.5
run("fixed 500 ms",           lambda i,r: base)
run("exponential, no jitter", lambda i,r: min(30,base*2**r))
run("exponential, full jitter",lambda i,r: random.uniform(0,min(30,base*2**r)))

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class FoodOrder {
    enum Status {
        CREATED, PAID, ACCEPTED, PICKED_UP, DELIVERED, CANCELLED;
    private static final Map<Status, Set<Status>> NEXT = Map.of(
        CREATED, Set.of(PAID, CANCELLED),
        PAID, Set.of(ACCEPTED, CANCELLED),
        ACCEPTED, Set.of(PICKED_UP, CANCELLED),
        PICKED_UP, Set.of(DELIVERED),
        DELIVERED, Set.of(),
        CANCELLED, Set.of());
    boolean canGo(Status to) { return NEXT.get(this).contains(to); }
}

record Event(String orderId, String type) {}

static class Order {
    final String id; final String user; final long totalPaise; Status status = Status.CREATED;
    Order(String id, String user, long totalPaise) {
        this.id = id; this.user = user; this.totalPaise = totalPaise;
    }
}

/** Fake gateway: the first charge for a key succeeds server-side but the reply is lost. */
static class Gateway {
    final Map<String, Long> charged = new HashMap<>();
    int calls = 0; boolean dropFirstReply = true;
    boolean charge(String key, long amount) {
        calls++;
        charged.putIfAbsent(key, amount);          // idempotent on the key
        if (dropFirstReply) { dropFirstReply = false; throw new RuntimeException("timeout"); }
        return true;
    }
    void refund(String key) { charged.remove(key); }
}

static class OrderService {
    final Map<String, Order> orders = new ConcurrentHashMap<>();
    final Map<String, String> byIdempotencyKey = new ConcurrentHashMap<>();
    final List<Event> outbox = new ArrayList<>();
    final Gateway gateway; int seq = 0;
    OrderService(Gateway g) { gateway = g; }

    synchronized Order place(String idemKey, String user, long total) {
        String existing = byIdempotencyKey.get(idemKey);
        if (existing != null) return orders.get(existing);          // duplicate request
        Order o = new Order("o-" + (++seq), user, total);
        orders.put(o.id, o); byIdempotencyKey.put(idemKey, o.id);
        outbox.add(new Event(o.id, "OrderCreated"));
        return o;
    }
    synchronized void pay(Order o) {
        for (int attempt = 1; attempt <= 3; attempt++) {
            try {
                gateway.charge("pay-" + o.id, o.totalPaise);        // same key on every retry
                move(o, Status.PAID, "OrderPaid"); return;
            } catch (RuntimeException e) {
                System.out.println("  payment attempt " + attempt + " failed: "
                    + e.getMessage());
            }
        }
        move(o, Status.CANCELLED, "OrderCancelled");
    }
    synchronized void restaurantReply(Order o, boolean accept) {
        if (accept) move(o, Status.ACCEPTED, "OrderAccepted");
        else {
            gateway.refund("pay-" + o.id);
            move(o, Status.CANCELLED, "OrderRejectedRefunded");
        }
    }
    synchronized void move(Order o, Status to, String eventType) {
        if (!o.status.canGo(to))
            throw new IllegalStateException(o.status + " -> " + to + " not allowed");
        o.status = to;
        outbox.add(new Event(o.id, eventType));   // same transaction in a real DB
    }
}

public static void main(String[] args) {
        Gateway gw = new Gateway();
        OrderService svc = new OrderService(gw);
        Order a = svc.place("key-123", "u1", 45_000);
        Order b = svc.place("key-123", "u1", 45_000);           // client retry of the same request
        System.out.println("same order returned for duplicate request: " + (a == b));
        svc.pay(a);
        System.out.println("gateway calls=" + gw.calls + ", distinct charges=" + gw.charged.size()
            + ", status=" + a.status);
        svc.restaurantReply(a, false);
        System.out.println("after rejection: status=" + a.status
            + ", charges left=" + gw.charged.size());
        try { svc.move(a, Status.DELIVERED, "x"); } catch (IllegalStateException e) {
            System.out.println("illegal transition blocked: " + e.getMessage());
        }
        Order c = svc.place("key-456", "u2", 30_000);
        svc.pay(c); svc.restaurantReply(c, true);
        svc.move(c, Status.PICKED_UP, "OrderPickedUp");
        svc.move(c, Status.DELIVERED, "OrderDelivered");
        System.out.println("order " + c.id + " final status=" + c.status);
        svc.outbox.forEach(e -> System.out.println("  outbox: " + e.orderId() + " " + e.type()));
    }
}
